-- GTA Local Online — database schema v1 (Phase 2 target, not created yet).
-- Written in the common subset of SQLite and PostgreSQL so the storage layer can switch drivers:
--   * TEXT uuids generated by the server, BIGINT money, TEXT ISO-8601 UTC timestamps
--   * JSON payloads stored as TEXT (SQLite json1 / PostgreSQL ::jsonb when migrated)
-- The server is the only writer. Clients never send SQL or raw rows, only validated messages.

CREATE TABLE schema_version (version INTEGER NOT NULL);
INSERT INTO schema_version VALUES (2);

CREATE TABLE players (                    -- an account (a person)
    uuid         TEXT PRIMARY KEY,
    name         TEXT NOT NULL UNIQUE,     -- login name, 2..24 chars [A-Za-z0-9 _.-]
    token_hash   TEXT NOT NULL,            -- SHA-256 of the per-player secret (never stored in clear)
    role         TEXT NOT NULL DEFAULT 'player',   -- player | admin (GodEye roles come later)
    created_at   TEXT NOT NULL,
    last_seen_at TEXT,
    banned       INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE characters (                 -- the freemode "YOU" character (one per player for now)
    uuid         TEXT PRIMARY KEY,
    player_uuid  TEXT NOT NULL REFERENCES players(uuid),
    name         TEXT NOT NULL,
    model        TEXT NOT NULL,            -- mp_m_freemode_01 | mp_f_freemode_01
    appearance   TEXT NOT NULL,            -- JSON: headBlend, faceFeatures, hair, overlays, components, props, tattoos
    state        TEXT NOT NULL,            -- JSON: health, armour, weapons, stats
    money        BIGINT NOT NULL DEFAULT 0,   -- wallet
    bank         BIGINT NOT NULL DEFAULT 0,   -- Maze Bank (schema v2)
    pos_x REAL NOT NULL, pos_y REAL NOT NULL, pos_z REAL NOT NULL, heading REAL NOT NULL,
    revision     INTEGER NOT NULL DEFAULT 0,   -- optimistic concurrency: saves must carry the current revision
    updated_at   TEXT NOT NULL
);
CREATE INDEX characters_player ON characters(player_uuid);

CREATE TABLE vehicles (                   -- persistent personal vehicles (Phase 5/8)
    uuid         TEXT PRIMARY KEY,
    owner_uuid   TEXT NOT NULL REFERENCES characters(uuid),
    model        TEXT NOT NULL,
    plate        TEXT NOT NULL,
    mods         TEXT NOT NULL DEFAULT '{}',   -- JSON
    health       REAL NOT NULL DEFAULT 1000,
    fuel         REAL NOT NULL DEFAULT 100,
    pos_x REAL, pos_y REAL, pos_z REAL, heading REAL,
    garage       TEXT,
    state        TEXT NOT NULL DEFAULT 'stored' CHECK (state IN ('stored', 'active', 'destroyed', 'impounded')),
    updated_at   TEXT NOT NULL
);
CREATE INDEX vehicles_owner ON vehicles(owner_uuid);

CREATE TABLE properties (
    uuid         TEXT PRIMARY KEY,
    owner_uuid   TEXT REFERENCES characters(uuid),
    kind         TEXT NOT NULL,
    data         TEXT NOT NULL DEFAULT '{}',
    updated_at   TEXT NOT NULL
);

CREATE TABLE inventory (
    character_uuid TEXT NOT NULL REFERENCES characters(uuid),
    item         TEXT NOT NULL,
    quantity     INTEGER NOT NULL CHECK (quantity >= 0),
    PRIMARY KEY (character_uuid, item)
);

CREATE TABLE economy_ledger (             -- every money change, so balances can be audited/rebuilt
    id           INTEGER PRIMARY KEY,
    character_uuid TEXT NOT NULL REFERENCES characters(uuid),
    delta        BIGINT NOT NULL,
    reason       TEXT NOT NULL,
    created_at   TEXT NOT NULL
);

CREATE TABLE world_state (                -- key/value for clock, weather, event flags
    key          TEXT PRIMARY KEY,
    value        TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

CREATE TABLE sessions (
    id           INTEGER PRIMARY KEY,
    player_uuid  TEXT NOT NULL REFERENCES players(uuid),
    address      TEXT NOT NULL,
    started_at   TEXT NOT NULL,
    ended_at     TEXT,
    end_reason   TEXT
);

CREATE TABLE permissions (
    player_uuid  TEXT NOT NULL REFERENCES players(uuid),
    permission   TEXT NOT NULL,
    PRIMARY KEY (player_uuid, permission)
);

CREATE TABLE events (                     -- audit log of authoritative events (joins, deaths, admin actions...)
    id           INTEGER PRIMARY KEY,
    at           TEXT NOT NULL,
    kind         TEXT NOT NULL,
    actor_uuid   TEXT,
    data         TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX events_at ON events(at);
